module protocol::asset;

use math::float::Decimal;
use protocol::interest::InterestModel;
use std::option::some;
use sui::dynamic_field;
use protocol::error;

public struct AssetConfig has copy, drop, store {
    /********
    when the principal and ratio of borrow indices are both small,
    the result can equal the principal, due to automatic truncation of division
    newDebt = debt * (current borrow index) / (original borrow index)
    so that the user could borrow without interest
    *********/
    min_borrow_amount: u64,
    /// max amount this asset can be borrow across the market
    max_borrow_amount: u64,
    /// max amount this asset can be deposited across the market
    max_deposit_amount: u64,
    /// fee rate paid to the protocol in repay
    repay_fee_rate: Decimal,

    liquidation_fee_rate: Decimal,
}

public struct Asset<phantom MarketType> has key, store {
    id: UID,
    // Indicates when flash loan is in progress
    flash_loan_lock: bool,
    interest_model: InterestModel,
    // dynamic fields:
    // - borrow: Option<AssetConfig>
    // - borrow_paused: bool,
    // - deposit_paused: bool,
    // - withdraw_paused: bool,
    // - liquidation_paused: bool,
    // - flash_loan_paused: bool,
}


// =============== Getter Functions =============
public fun flash_loan_ongoing<MarketType>(self: &Asset<MarketType>): bool { self.flash_loan_lock }

public fun borrow_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<BorrowPaused, bool>(&self.id, BorrowPaused {}) }
public fun deposit_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<DepositPaused, bool>(&self.id, DepositPaused {}) }
public fun withdraw_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<WithdrawPaused, bool>(&self.id, WithdrawPaused {}) }
public fun liquidation_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<LiquidationPaused, bool>(&self.id, LiquidationPaused {}) }
public fun flash_loan_paused<MarketType>(self: &Asset<MarketType>): bool { *dynamic_field::borrow<FlashLoanPaused, bool>(&self.id, FlashLoanPaused {}) }

public fun min_borrow_amount(self: &AssetConfig): u64 { self.min_borrow_amount }
public fun max_borrow_amount(self: &AssetConfig): u64 { self.max_borrow_amount }
public fun max_deposit_amount(self: &AssetConfig): u64 { self.max_deposit_amount }
public fun repay_fee_rate(self: &AssetConfig): Decimal { self.repay_fee_rate }
public fun liquidation_fee_rate(self: &AssetConfig): Decimal { self.liquidation_fee_rate }


public(package) fun asset_config<MarketType>(self: &Asset<MarketType>): &AssetConfig {
    dynamic_field::borrow<DFKey<AssetConfig>, Option<AssetConfig>>(
        &self.id,
        DFKey<AssetConfig> {},
    ).borrow()
}

public(package) fun interest_model<MarketType>(self: &Asset<MarketType>): &InterestModel {
    &self.interest_model
}

// ================= Constructor ================
public(package) fun new<MarketType>(
    interest_model: InterestModel,
    borrow: AssetConfig,
    ctx: &mut TxContext,
): Asset<MarketType> {
    let mut asset = Asset {
        id: object::new(ctx),
        flash_loan_lock: false,
        interest_model,
    };

    dynamic_field::add(&mut asset.id, DFKey<AssetConfig> {}, some<AssetConfig>(borrow));

    dynamic_field::add(&mut asset.id, BorrowPaused {}, false);
    dynamic_field::add(&mut asset.id, DepositPaused {}, false);
    dynamic_field::add(&mut asset.id, WithdrawPaused {}, false);
    dynamic_field::add(&mut asset.id, LiquidationPaused {}, false);
    dynamic_field::add(&mut asset.id, FlashLoanPaused {}, false);

    asset
}

/// Create a new shared asset configuration across all emodes in a market
public(package) fun new_asset_config(
    min_borrow_amount: u64,
    max_borrow_amount: u64,
    repay_fee_rate: Decimal,
    max_deposit_amount: u64,
    liquidation_fee_rate: Decimal,
): AssetConfig {
    AssetConfig {
        min_borrow_amount,
        max_borrow_amount,
        repay_fee_rate,
        max_deposit_amount,
        liquidation_fee_rate,
    }
}

public(package) fun update_interest_model<MarketType>(
    self: &mut Asset<MarketType>,
    model: InterestModel,
) {
    self.interest_model = model;
}

fun assert_not_equal_and_set<Name: copy + drop + store>(id: &mut UID, name: Name, v: bool) {
    let current = dynamic_field::borrow_mut<Name, bool>(id, name);
    assert!(*current != v, error::updating_with_same_value());
    *current = v;
}

public(package) fun change_operation_status<MarketType>(self: &mut Asset<MarketType>, what: u8, is_paused: bool) {
    match (what) {
        0 => assert_not_equal_and_set<BorrowPaused>(&mut self.id, BorrowPaused {}, is_paused),
        1 => assert_not_equal_and_set<DepositPaused>(&mut self.id, DepositPaused {}, is_paused),
        2 => assert_not_equal_and_set<WithdrawPaused>(&mut self.id, WithdrawPaused {}, is_paused),
        3 => assert_not_equal_and_set<LiquidationPaused>(&mut self.id, LiquidationPaused {}, is_paused),
        4 => assert_not_equal_and_set<FlashLoanPaused>(&mut self.id, FlashLoanPaused {}, is_paused),
        _ => { abort(error::invalid_operation_status()) }
    };
}

public(package) fun update_asset_config<MarketType>(
    self: &mut Asset<MarketType>,
    config: AssetConfig
) {
    let b = dynamic_field::borrow_mut<DFKey<AssetConfig>, Option<AssetConfig>>(
        &mut self.id,
        DFKey<AssetConfig> {},
    );
    *b = some(config);
}

// ================== Updater ===================

public(package) fun flash_loan_triggered<MarketType>(self: &mut Asset<MarketType>) {
    self.flash_loan_lock = true;
}

public(package) fun flash_loan_finished<MarketType>(self: &mut Asset<MarketType>) {
    self.flash_loan_lock = false;
}

public struct DFKey<phantom T> has copy, drop, store {}
public struct BorrowPaused has copy, drop, store {}
public struct DepositPaused has copy, drop, store {}
public struct WithdrawPaused has copy, drop, store {}
public struct LiquidationPaused has copy, drop, store {}
public struct FlashLoanPaused has copy, drop, store {}

/// @title A module dedicated for handling the borrow request from user
module protocol::borrow;

use std::type_name::{Self, TypeName};
use sui::clock::{Self, Clock};
use sui::coin::{Self, Coin};
use sui::event::emit;

use math::float::Decimal;

use x_oracle::x_oracle::XOracle;

use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_borrow_reward_type;
use protocol::app::ProtocolApp;

public struct BorrowEvent has copy, drop {
    borrower: address,

    market: TypeName,
    obligation: ID,

    asset: TypeName,

    amount: u64,
    total_borrow: Decimal,
    borrow_index: Decimal,

    time: u64,
}

public fun borrow<MarketType, CoinType>(
    app: &ProtocolApp,
    obligation_owner_cap: &ObligationOwnerCap,
    market: &mut Market<MarketType>,
    coin_decimals_registry: &CoinDecimalsRegistry,
    borrow_amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.ensure_version_matches();
    app.validate_market<MarketType>(market);

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = clock::timestamp_ms(clock) / 1000;

    let (borrowed_balance, borrow_index, total_borrow) = market.handle_borrow(
        obligation_owner_cap.id(),
        borrow_amount,
        coin_decimals_registry,
        x_oracle,
        clock,
        now
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_borrow_reward_type(),
        obligation_owner_cap.id(),
        total_borrow.floor(),
        clock
    );

    // Emit the borrow event
    emit(BorrowEvent {
        borrower: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        asset: type_name::with_defining_ids<CoinType>(),
        amount: borrow_amount,

        total_borrow,
        borrow_index,

        time: now,
    });

    coin::from_balance(borrowed_balance, ctx)
}

/// @title Module for hanlding withdraw base asset request from user
/// @notice User use sCoin to redeem the underlying asset
module protocol::withdraw;

use std::type_name::{Self, TypeName};
use sui::clock::Clock;
use sui::event::emit;
use sui::coin::Coin;

use x_oracle::x_oracle::XOracle;

use protocol::app::ProtocolApp;
use protocol::coin_decimals_registry::CoinDecimalsRegistry;
use protocol::ctoken::CToken;
use protocol::market::Market;
use protocol::obligation::ObligationOwnerCap;
use protocol::liquidity_miner::get_deposit_reward_type;

public struct WithdrawEvent has copy, drop {
    redeemer: address,

    market: TypeName,
    obligation: ID,

    withdraw_asset: TypeName,
    withdraw_amount: u64,
    ctokens_remaining: u64,

    burn_asset: TypeName,
    burn_amount: u64,
    time: u64,
}

public fun withdraw_as_coin<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    ctoken_to_burn: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
): Coin<CoinType> {
    app.validate_market<MarketType>(market);
    app.ensure_version_matches();

    assert!(!market.has_circuit_break_triggered(), protocol::error::market_under_circuit_break());

    let now = sui::clock::timestamp_ms(clock) / 1000;

    let (coin, ctokens_remaining) = market.handle_withdraw<MarketType, CoinType>(
        obligation_owner_cap.id(),
        ctoken_to_burn,
        coin_decimals_registry,
        x_oracle,
        clock,
        now,
        ctx,
    );

    let miner = market.borrow_liquidity_mining_mut<MarketType>();
    miner.update_obligation_reward_manager<MarketType, CoinType>(
        get_deposit_reward_type(),
        obligation_owner_cap.id(),
        ctokens_remaining,
        clock
    );

    // emit Redeem Event
    emit(WithdrawEvent {
        redeemer: ctx.sender(),

        market: type_name::with_defining_ids<MarketType>(),
        obligation: obligation_owner_cap.id(),

        withdraw_asset: type_name::with_defining_ids<CoinType>(),
        withdraw_amount: coin.value(),
        ctokens_remaining,

        burn_asset: type_name::with_defining_ids<CToken<MarketType, CoinType>>(),
        burn_amount: ctoken_to_burn,

        time: now,
    });

    coin
}

#[allow(lint(self_transfer))]
public fun withdraw<MarketType, CoinType>(
    app: &ProtocolApp,
    market: &mut Market<MarketType>,
    obligation_owner_cap: &ObligationOwnerCap,
    coin_decimals_registry: &CoinDecimalsRegistry,
    amount: u64,
    x_oracle: &XOracle,
    clock: &Clock,
    ctx: &mut TxContext,
) {
    let coin = withdraw_as_coin<MarketType, CoinType>(
        app,
        market,
        obligation_owner_cap,
        coin_decimals_registry, 
        amount, 
        x_oracle, 
        clock, 
        ctx
    );
    transfer::public_transfer(coin, ctx.sender());
}

